head.script:
// https://inswave01.atlassian.net/browse/WAEA-880



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setHeaderDisabled]<br/>Header Column 정보를 사용하여 특정 Header Column 의 disabled 상태를 설정합니다.",
    "validation" : [
        "headerId(필수) 파라미터로 disabled 상태를 설정할 Header Column 의 ID 를 설정할 수 있어야 합니다.",
        "disabled(선택) 파라미터를 true 로 설정 시 Header Column 을 disabled 상태로 설정해야 합니다.",
        "disabled(선택) 파라미터를 false 로 설정 시 Header Column 의 disabled 상태를 해제해야 합니다.",
        "disabled(선택) 파라미터 생략 시 기본값 false 로 동작해야 합니다.",
        "disabled 상태인 Header Column 은 onheaderclick 이벤트 발생이 차단되어야 합니다.",
        "disabled 상태인 Header Column 은 onheadertextimageclick 이벤트 발생이 차단되어야 합니다.",        
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="Header Column 1(column2) 은 숨겨진 상태 / Header 클릭 시 onheaderclick 핸들러가 출력되며 disabled 인 Header 는 출력되지 않음"', '', 'label1');

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // Header 이벤트 핸들러 부착 (disabled 시 차단 여부 검증)
    let eList = $c.gcm.createEList(["onheaderclick", "onheadertextimageclick"]);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (custom : column1, column3 을 textImage Header 로 설정하여 onheadertextimageclick 검증 가능하게 구성)
    await scwin.createTextImageGridView(cList, eList);

    // 두번째 컬럼 숨김 (숨겨진 Column 도 인덱스에 포함됨)
    target1.setColumnVisible(1, false);
}



// textImage Header 를 포함한 gridView 직접 생성 ($p.dynamicCreate)
// column1, column3 : inputType="textImage" (Header image 클릭 시 onheadertextimageclick 발생)
// column2, column4 : inputType="text" (Header 클릭 시 onheaderclick 발생)
scwin.createTextImageGridView = async function (cList, eList) {
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup('');
    let imageSrc = '/cm/images/base/ico_grid_del.svg';

    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="textImage" viewType="icon" imageSrc="' + imageSrc + '" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="textImage" viewType="icon" imageSrc="' + imageSrc + '" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



scwin.btn_setHeaderDisabled_onclick = function () {
    let headerId = par_headerId.getValue();
    let disabledText = par_disabled.getValue();

    if (disabledText === 'omit') {
        // 파라미터 생략 (기본값 false)
        target1.setHeaderDisabled(headerId);
        wf_body_bottom.getObj("scwin").setReturnValue("setHeaderDisabled('" + headerId + "')");
    } else {
        let disabled = disabledText === 'true';
        target1.setHeaderDisabled(headerId, disabled);
        wf_body_bottom.getObj("scwin").setReturnValue("setHeaderDisabled('" + headerId + "', " + disabled + ")");
    }
    // 설정 후 해당 Header 를 클릭하여 onheaderclick / onheadertextimageclick 발생 여부로 disabled 차단 확인
}



scwin.target1_onheaderclick = function (headerId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onheaderclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("headerId : " + headerId);
}



scwin.target1_onheadertextimageclick = function (headerId, headerValue) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onheadertextimageclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("headerId : " + headerId);
    wf_body_bottom.getObj("scwin").setReturnValue("headerValue : " + headerValue);
}
